FILE: app/src/limited-orbit.ts
```ts
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl, setCameraLimits } from "@babylonjs/lite";

export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  // Set the radius limits so the library clamps zoom (including inertial
  // drift) to the allowed range on every frame.
  const removeLimits = setCameraLimits(
    camera,
    { lowerRadiusLimit: minDistance, upperRadiusLimit: maxDistance },
    scene,
  );

  // If the camera starts outside the range, bring it inside now.
  if (camera.radius < minDistance) {
    camera.radius = minDistance;
  } else if (camera.radius > maxDistance) {
    camera.radius = maxDistance;
  }

  // Attach the standard orbit controls: drag to orbit, wheel / pinch to zoom.
  const removeControls = attachControl(camera, canvas, scene);

  return () => {
    removeControls();
    removeLimits();
  };
}
```

I wrote `src/limited-orbit.ts` which sets `lowerRadiusLimit`/`upperRadiusLimit` via the library's `setCameraLimits` (so the built-in control code clamps the radius on every frame, including inertial drift), clamps the radius immediately if it starts out of range, and attaches the standard orbit controls via `attachControl`; the returned cleanup removes both. The one thing I'm not 100 % sure of is whether `setCameraLimits` with only the two radius fields leaves the alpha/beta limits untouched (the type says all fields are optional, so it should, but I can't verify the runtime behaviour without the library source).
